<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $vehicle->plaka }} · {{ $vehicle->marka }} {{ $vehicle->model }}</title><style>:root{--blue:#176b87;--green:#0f9d78;--ink:#17324d}*{box-sizing:border-box}body{margin:0;background:#f4f8fa;color:var(--ink);font-family:system-ui}.wrap{width:min(920px,calc(100% - 2rem));margin:2rem auto}.hero{background:linear-gradient(135deg,var(--blue),var(--green));color:#fff;padding:2.4rem;border-radius:26px}.card{background:#fff;border-radius:18px;padding:1.3rem;box-shadow:0 7px 26px #16324d12;margin-top:1rem}.facts{display:flex;flex-wrap:wrap;gap:1rem}.fact{background:#ffffff20;padding:.7rem 1rem;border-radius:12px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:.8rem}.gallery img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:13px}.row{padding:.8rem 0;border-bottom:1px solid #e5edf2}.muted{color:#64748b}</style></head><body><main class="wrap"><section class="hero"><small>ARAÇ VİTRİNİ</small><h1>{{ $vehicle->plaka }}</h1><h2>{{ $vehicle->marka }} {{ $vehicle->model }}</h2><div class="facts">@if($vehicle->model_yili)<div class="fact">{{ $vehicle->model_yili }} model</div>@endif @if($vehicle->renk)<div class="fact">{{ $vehicle->renk }}</div>@endif<div class="fact">{{ number_format($vehicle->guncel_km,0,',','.') }} km</div></div></section>@if($vehicle->donanimlar)<section class="card"><h2>Donanım ve özellikler</h2><p>{{ implode(' · ',$vehicle->donanimlar) }}</p></section>@endif @if($media->isNotEmpty())<section class="card"><h2>Galeri</h2><div class="gallery">@foreach($media as $m)<a href="{{ route('vehicle.showcase.media',[$vehicle->plate_key,$m]) }}">@if(str_starts_with($m->mime_type,'image/'))<img src="{{ route('vehicle.showcase.media',[$vehicle->plate_key,$m]) }}" alt="{{ $m->caption }}">@else{{ $m->caption?:'Video' }}@endif</a>@endforeach</div></section>@endif<section class="card"><h2>Bakım ve servis geçmişi</h2>@forelse($serviceHistory as $item)<div class="row"><strong>{{ $item->tarih->format('d.m.Y') }}</strong><div class="muted">{{ $item->public_summary }}</div></div>@empty<p class="muted">Paylaşılmış servis kaydı yok.</p>@endforelse</section></main></body></html>
